// FactBusinessCosts — generated by src/powerbi/build_assets.py from FactBusinessCosts.csv
// Grain/keys: see powerbi/data_model.md
let
    Source   = Csv.Document(File.Contents(DataFolder & "FactBusinessCosts.csv"),
                            [Delimiter = ",", Encoding = 65001, QuoteStyle = QuoteStyle.Csv]),
    Promoted = Table.PromoteHeaders(Source, [PromoteAllScalars = true]),
    Typed    = Table.TransformColumnTypes(Promoted, {
        {"cost_id", type text},
        {"department_id", type text},
        {"cost_date", type date},
        {"cost_category", type text},
        {"direct_cost", Currency.Type},
        {"indirect_cost", Currency.Type},
        {"total_cost", Currency.Type}
    }, "en-US")
in
    Typed
